style.css:
/* Общие настройки для body */
body {
    background-color: #d9a6ff; /* Светло-фиолетовый цвет для фона */
    color: #f8d7e5; /* Нежно-светло-розовый цвет текста */
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    overflow: hidden;
}

/* Фон с гифкой */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: url('https://i.gifer.com/g32K.gif'); /* Замените ссылку на нужную гифку */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    opacity: 0.4; /* Прозрачность гифки, чтобы не отвлекала */
    z-index: -1; /* Чтобы гифка была на заднем плане */
}

/* Настройки заголовков */
h1, h2, h3, h4, h5, h6 {
    color: #4d1a73; /* Темно-фиолетовый цвет для заголовков */
}

/* Настройки ссылок */
a {
    color: #4d1a73; /* Темно-фиолетовый цвет ссылок */
    text-decoration: none;
}

a:hover {
    color: #6a239b; /* Более насыщенный темно-фиолетовый при наведении */
    text-decoration: underline;
}

/* Настройки кнопок */
button {
    background-color: #e0b3ff; /* Светло-фиолетовый цвет кнопок */
    color: #4d1a73; /* Темно-фиолетовый текст */
    border: none;
    padding: 10px 20px;
    cursor: pointer;
    border-radius: 5px;
}

button:hover {
    background-color: #f8d7e5; /* Нежно-светло-розовый при наведении */
}

/* Настройка текстовых полей */
input[type="text"], textarea {
    background-color: #d9a6ff; /* Светло-фиолетовый фон полей ввода */
    color: #4d1a73; /* Темно-фиолетовый текст */
    border: 1px solid #4d1a73; /* Темно-фиолетовая рамка */
    padding: 10px;
    border-radius: 5px;
}

/* Для панели навигации */
nav {
    background-color: #e0b3ff; /* Светло-фиолетовый фон панели навигации */
    padding: 15px;
    text-align: center;
}

nav a {
    color: #4d1a73; /* Темно-фиолетовый цвет ссылок */
    padding: 10px 20px;
}

nav a:hover {
    color: #f8d7e5; /* Нежно-светло-розовый цвет при наведении */
}

/* Анимация для элементов */
button, a, input[type="text"], textarea {
    transition: background-color 0.3s ease, color 0.3s ease;
}

/* Текст, который был белым, теперь стал нежно-светло-розовым */
h1, h2, h3, h4, h5, h6, button, a, input[type="text"], textarea, nav a:hover {
    color: #f8d7e5; /* Нежно-светло-розовый цвет текста */
}
